// Local state for the Datasets tab.
//
// A dataset is rows plus ledger events (§6): creating one writes a row, adding
// a capture writes a membership, and NOTHING moves on disk. So this hook does
// not orchestrate an export — it reads two lists (`GET /datasets`,
// `GET /captures`), joins the memberships the capture list already carries, and
// sends the four mutations §6 defines. The browsable `views/` tree is
// regenerated by the server after each of those mutations; there is deliberately
// no refresh call here, because a second writer racing the one owner is how a
// symlink tree ends up disagreeing with the catalog.
//
// The addressable slice of this state (both searches, the facets, the sort, the
// selected dataset + member) is seeded from the query string on mount and
// mirrored back into it on every change, so a view is shareable, survives a
// reload, and survives a tab round-trip — the shell unmounts this screen on a
// tab switch, which would otherwise discard everything. See url.ts for the key
// contract; `replaceState` (not push) keeps a keystroke-by-keystroke search out
// of the browser's history.
//
// Both selections are stored as IDENTITY (dataset_id, membership_id) and then
// DERIVED from the freshly loaded data. That is what lets a deep link restore a
// selection before the lists have finished loading, and what makes a removed
// member degrade to "nothing selected" instead of leaving a destructive control
// pointed at a row that is no longer on screen.

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { apiGet } from '../../api/client';
import {
  addDatasetMember,
  archiveCapture,
  createDataset,
  deleteDataset,
  getArchiveConfig,
  getCapture,
  getDataset,
  listAllCaptures,
  listDatasets,
  removeDatasetMember,
} from '../../api/captures';
import { queryKeys } from '../../api/queryKeys';
import type { Capture, CaptureDetail } from '../../api/types';
import { availabilityOf } from '../captures/availability';
import { captureErrorText } from '../captures/errors';
import { useCaptureDeletion, type CaptureDeletionState } from '../captures/useCaptureDeletion';
import {
  ANY_OPERATOR,
  MEMBER_PAGE_SIZE,
  aggregate,
  buildDatasetRows,
  datasetMatchesSearch,
  distinctOperators,
  filterMembers,
  findDataset,
  indexCaptures,
  joinMembers,
  membersByDataset,
  type DatasetAggregate,
  type DatasetRow,
  type MemberRow,
  type SortMode,
  type TaskResultFilter,
} from './data';
import { readDatasetsUrl, writeDatasetsUrl } from './url';

export type { TaskResultFilter } from './data';

/** This screen's own capture sweep: the whole catalog, because a dataset may
 *  cite any capture in it and the "add a capture" picker offers from all of it.
 *  A different shape from any per-page list, so it gets its own cache entry. */
const CAPTURE_SCOPE = 'datasets';

/** Capture states that may be added to a dataset: a recording that has finished,
 *  one way or another. A live recording has no final bytes to cite, and a
 *  tombstone (§7) has none left. */
const ADDABLE_STATES = new Set(['completed', 'failed', 'interrupted']);

/** How many candidate captures the rail builds at once. The rest are reachable
 *  by narrowing the search — the boundary is stated, never silent. */
const CANDIDATE_LIMIT = 50;

/** The scope the center's summary describes: the selected dataset, or — when
 *  none is selected — every member of every dataset in view. */
export interface ScopeSummary {
  kind: 'dataset' | 'catalog';
  /** Header label (the dataset's name, or "All datasets"). */
  label: string;
  operator: string | null;
  task: string | null;
  aggregate: DatasetAggregate;
  /** Members the aggregate could say nothing about (§ see DatasetRow). */
  unresolved: number;
}

export interface DatasetsState {
  /** The dataset rows the left column renders (search-filtered, sorted). */
  rows: DatasetRow[];
  /** Datasets surviving the search. */
  shown: number;
  /** Datasets before filtering (to say "showing n of m" honestly). */
  total: number;

  search: string;
  setSearch: (s: string) => void;
  sort: SortMode;
  toggleSort: () => void;

  taskResultFilter: TaskResultFilter;
  setTaskResultFilter: (f: TaskResultFilter) => void;
  operatorFilter: string;
  setOperatorFilter: (o: string) => void;
  /** Distinct operators across the loaded captures (facet choices). */
  operatorOptions: string[];

  // ---- dataset selection -------------------------------------------------
  selectedDatasetId: string | null;
  selectedDataset: DatasetRow | null;
  selectDataset: (datasetId: string) => void;
  isDatasetSelected: (datasetId: string) => boolean;
  clearDataset: () => void;

  // ---- creating a dataset (§6: a row, nothing on disk) -------------------
  createOpen: boolean;
  openCreate: () => void;
  cancelCreate: () => void;
  newName: string;
  setNewName: (s: string) => void;
  newOperator: string;
  setNewOperator: (s: string) => void;
  newTask: string;
  setNewTask: (s: string) => void;
  submitCreate: () => void;
  creating: boolean;
  createError: unknown;

  // ---- deleting a dataset (rows only; no capture is touched) -------------
  confirmingDatasetDelete: boolean;
  requestDatasetDelete: () => void;
  cancelDatasetDelete: () => void;
  confirmDatasetDelete: () => void;
  deletingDataset: boolean;
  datasetDeleteError: unknown;

  // ---- members -----------------------------------------------------------
  /** Member-row search inside the center pane (distinct from the list search). */
  memberSearch: string;
  setMemberSearch: (s: string) => void;
  /** Every member in the current scope after the facets — the denominator for
   *  "n of m" in the center pane. */
  scopeMembers: MemberRow[];
  /** scopeMembers narrowed by memberSearch and CAPPED at one page — the rows
   *  actually built into the DOM. */
  memberRows: MemberRow[];
  /** How many members match in the scope before the page cap. */
  memberMatchCount: number;
  page: number;
  pageCount: number;
  pageSize: number;
  goToPage: (page: number) => void;
  scope: ScopeSummary;

  // Member selection. selectMember TOGGLES: clicking the already-selected row
  // (or the summary row) clears it and returns to the summary.
  selected: MemberRow | null;
  selectMember: (row: MemberRow) => void;
  isMemberSelected: (row: MemberRow) => boolean;
  selectSummary: () => void;
  /** True when no member is selected — the bottom pane shows the scope summary. */
  isSummaryActive: boolean;

  /** The selected member's capture, with its sidecars. */
  detail: CaptureDetail | null;
  detailLoading: boolean;
  detailError: boolean;

  removeMember: (row: MemberRow) => void;
  /** membership_id currently being removed, or null. */
  removingMembershipId: string | null;

  // ---- adding a capture --------------------------------------------------
  /** Finished captures not already in the selected dataset, newest first and
   *  capped at CANDIDATE_LIMIT. */
  candidates: Capture[];
  /** How many matched before the cap, so the rail can say what it is not
   *  showing. */
  candidateMatchCount: number;
  candidateSearch: string;
  setCandidateSearch: (s: string) => void;
  addMember: (capture: Capture) => void;
  addingCaptureId: string | null;

  // ---- removing the bytes (§7, via the shared dialogs) -------------------
  deletion: CaptureDeletionState;
  /** True on a split deployment, so the discard dialog says — unprompted — that
   *  a copy may still exist on the robot (§12). */
  splitDeploy: boolean;

  // ---- archive (§6: per capture, and NOT a job) --------------------------
  // Copies a capture out, verifies it, then removes the source. `archiveEnabled`
  // is false when the deployment configured no roots — the control is then not
  // rendered at all, because it could only ever fail.
  archiveEnabled: boolean;
  archiveRoots: string[];
  /** True when this capture may be archived at all: the backend refuses a
   *  capture that is still in any dataset, exactly as it refuses a delete. */
  canArchive: (capture: Capture) => boolean;
  archiveTarget: Capture | null;
  openArchive: (capture: Capture) => void;
  cancelArchive: () => void;
  archiveRoot: string;
  setArchiveRoot: (root: string) => void;
  archiveSubpath: string;
  setArchiveSubpath: (path: string) => void;
  /** The destination sent to the server. The server appends the capture id
   *  under it, so this is the PARENT of what lands on disk. */
  archiveDestination: string;
  /** Where the files actually land — `<destination>/<capture_id>`. */
  archiveFinalPath: string;
  archiveReason: string;
  setArchiveReason: (s: string) => void;
  confirmArchive: () => void;
  archiving: boolean;
  archiveError: unknown;

  isLoading: boolean;
  isError: boolean;

  toast: string;
}

/** Milliseconds a search box may keep typing before the lists are refiltered.
 *  Long enough to swallow a fast typist's keystrokes, short enough that a pause
 *  reads as "it kept up" rather than "it is thinking". */
const SEARCH_DEBOUNCE_MS = 150;

/** *value*, but only after it has stopped changing for *delay* ms. */
function useDebounced<T>(value: T, delay: number): T {
  const [settled, setSettled] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setSettled(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return settled;
}

const TOAST_MS = 2400;

/** Case-insensitive substring match over a capture's own identifying fields —
 *  the candidate picker's find. */
function captureMatches(capture: Capture, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return [capture.capture_id, capture.run_id, capture.operator, capture.task]
    .filter((v): v is string => typeof v === 'string' && v !== '')
    .some((v) => v.toLowerCase().includes(q));
}

export function useDatasetsState(): DatasetsState {
  const queryClient = useQueryClient();
  // Seed every addressable field from the query string ONCE — this is what a
  // deep link, a reload, and a return to the tab (the shell unmounts this
  // screen on a tab switch) all restore from.
  const [seed] = useState(() => readDatasetsUrl(window.location.search));

  const [selectedDatasetId, setSelectedDatasetId] = useState<string | null>(seed.datasetId);
  const [selectedMembershipId, setSelectedMembershipId] = useState<string | null>(
    seed.membershipId,
  );
  const [search, setSearch] = useState(seed.search);
  const [memberSearch, setMemberSearch] = useState(seed.memberSearch);
  const [sort, setSort] = useState<SortMode>(seed.sort);
  const [taskResultFilter, setTaskResultFilter] = useState<TaskResultFilter>(
    seed.taskResultFilter,
  );
  const [operatorFilter, setOperatorFilter] = useState<string>(seed.operatorFilter);
  const [page, setPage] = useState(1);

  const [createOpen, setCreateOpen] = useState(false);
  const [newName, setNewName] = useState('');
  const [newOperator, setNewOperator] = useState('');
  const [newTask, setNewTask] = useState('');
  const [confirmingDatasetDelete, setConfirmingDatasetDelete] = useState(false);
  const [candidateSearch, setCandidateSearch] = useState('');
  const [archiveTarget, setArchiveTarget] = useState<Capture | null>(null);
  const [archiveRoot, setArchiveRoot] = useState('');
  const [archiveSubpath, setArchiveSubpath] = useState('');
  const [archiveReason, setArchiveReason] = useState('');
  const [toast, setToast] = useState('');
  const toastTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const showToast = useCallback((message: string) => {
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    setToast(message);
    toastTimerRef.current = setTimeout(() => setToast(''), TOAST_MS);
  }, []);

  useEffect(
    () => () => {
      if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    },
    [],
  );

  // ---- reads -------------------------------------------------------------

  const listQuery = useQuery({
    queryKey: queryKeys.datasets,
    queryFn: ({ signal }) => listDatasets(signal),
  });
  const datasets = useMemo(() => listQuery.data?.items ?? [], [listQuery.data]);

  const capturesQuery = useQuery({
    queryKey: queryKeys.captureList(CAPTURE_SCOPE),
    queryFn: ({ signal }) => listAllCaptures({}, signal),
  });
  const captures = useMemo(() => capturesQuery.data?.items ?? [], [capturesQuery.data]);
  const capturesById = useMemo(() => indexCaptures(captures), [captures]);

  // The selected dataset's members come from its own endpoint rather than from
  // the memberships on the captures: it is the authority on what belongs to it,
  // and it still lists a member whose capture never reached this host — which
  // the capture-side join structurally cannot.
  const detailQuery = useQuery({
    queryKey: queryKeys.dataset(selectedDatasetId ?? ''),
    queryFn: ({ signal }) => getDataset(selectedDatasetId ?? '', signal),
    enabled: selectedDatasetId !== null,
  });

  const debouncedSearch = useDebounced(search, SEARCH_DEBOUNCE_MS);
  const debouncedMemberSearch = useDebounced(memberSearch, SEARCH_DEBOUNCE_MS);
  const debouncedCandidateSearch = useDebounced(candidateSearch, SEARCH_DEBOUNCE_MS);

  const membersByDatasetId = useMemo(() => membersByDataset(captures), [captures]);
  const allRows = useMemo(
    () => buildDatasetRows(datasets, membersByDatasetId, sort),
    [datasets, membersByDatasetId, sort],
  );
  const rows = useMemo(
    () => allRows.filter((row) => datasetMatchesSearch(row, debouncedSearch)),
    [allRows, debouncedSearch],
  );

  // The selected dataset is DERIVED from the loaded list, so a search that hides
  // it — or a deletion that removed it — degrades to "nothing selected" rather
  // than leaving stale rows and a live Delete on screen.
  const selectedRow = useMemo(
    () => findDataset(rows, selectedDatasetId),
    [rows, selectedDatasetId],
  );

  const operatorOptions = useMemo(() => distinctOperators(captures), [captures]);

  // Scope members: the selected dataset's authoritative member list joined to
  // the captures, else every member of every dataset in view.
  const scopeAllMembers = useMemo(() => {
    if (selectedRow) {
      const members = detailQuery.data?.members;
      // Until the detail lands, the capture-side join is what we honestly have.
      return members ? joinMembers(members, capturesById) : selectedRow.members;
    }
    return rows.flatMap((row) => row.members);
  }, [selectedRow, detailQuery.data, capturesById, rows]);

  const scopeMembers = useMemo(
    () =>
      filterMembers(scopeAllMembers, {
        search: '',
        taskResultFilter,
        operatorFilter,
      }),
    [scopeAllMembers, taskResultFilter, operatorFilter],
  );

  const matchedMembers = useMemo(
    () =>
      filterMembers(scopeMembers, {
        search: debouncedMemberSearch,
        taskResultFilter: 'all',
        operatorFilter: ANY_OPERATOR,
      }),
    [scopeMembers, debouncedMemberSearch],
  );

  const scopeAggregate = useMemo(() => aggregate(scopeMembers), [scopeMembers]);
  const scope: ScopeSummary = useMemo(() => {
    if (selectedRow) {
      return {
        kind: 'dataset',
        label: selectedRow.dataset.name,
        operator: selectedRow.dataset.operator ?? null,
        task: selectedRow.dataset.task ?? null,
        aggregate: scopeAggregate,
        unresolved: selectedRow.unresolved,
      };
    }
    return {
      kind: 'catalog',
      label: 'All datasets',
      operator: null,
      task: null,
      aggregate: scopeAggregate,
      unresolved: rows.reduce((sum, row) => sum + row.unresolved, 0),
    };
  }, [selectedRow, scopeAggregate, rows]);

  const pageCount = Math.max(1, Math.ceil(matchedMembers.length / MEMBER_PAGE_SIZE));
  // Anything that changes WHICH members are on screen returns to page one —
  // page 4 of a dataset that no longer has 800 members is an empty table, and
  // the operator did not ask to go there.
  useEffect(() => {
    setPage(1);
  }, [selectedDatasetId, debouncedMemberSearch, debouncedSearch, taskResultFilter, operatorFilter]);
  // Clamp rather than trust: a page can fall out of range when rows disappear
  // under an already-open view (a removal, a refetch), and reading past the end
  // must never render a blank table.
  const currentPage = Math.min(Math.max(1, page), pageCount);
  const memberRows = useMemo(
    () =>
      matchedMembers.slice(
        (currentPage - 1) * MEMBER_PAGE_SIZE,
        currentPage * MEMBER_PAGE_SIZE,
      ),
    [matchedMembers, currentPage],
  );

  // The selected MEMBER is derived for a sharper reason than stale rows: the
  // detail pane carries live Remove and Delete controls. A filter must never
  // leave a destructive control pointed at an off-screen target.
  const selected = useMemo(
    () => scopeMembers.find((row) => row.membershipId === selectedMembershipId) ?? null,
    [scopeMembers, selectedMembershipId],
  );

  const captureDetailQuery = useQuery({
    queryKey: queryKeys.capture(selected?.captureId ?? ''),
    queryFn: ({ signal }) => getCapture(selected?.captureId ?? '', signal),
    enabled: selected?.captureId !== undefined && selected?.capture !== null,
  });

  // ---- selection ---------------------------------------------------------

  const selectDataset = useCallback((datasetId: string) => {
    setSelectedDatasetId(datasetId);
    setSelectedMembershipId(null); // switching datasets clears the member selection
    setMemberSearch(''); // and its one-shot find
  }, []);
  const clearDataset = useCallback(() => {
    setSelectedDatasetId(null);
    setSelectedMembershipId(null);
  }, []);
  const selectMember = useCallback((row: MemberRow) => {
    setSelectedMembershipId((cur) => (cur === row.membershipId ? null : row.membershipId));
  }, []);
  const selectSummary = useCallback(() => setSelectedMembershipId(null), []);

  const toggleSort = useCallback(
    () => setSort((s) => (s === 'recent' ? 'alpha' : 'recent')),
    [],
  );

  // Mirror the addressable state back into the query string, so the view is
  // shareable, survives a reload, and is still there after a tab round-trip.
  // `replaceState` (not push) — a search box typed character by character must
  // not fill the history stack. `tab` / `solo` are carried through untouched:
  // they belong to the shell, which likewise rebuilds the query string from
  // window.location.search and so preserves these keys in return.
  //
  // Both selections are written from the STORED identity rather than the
  // resolved row, so a deep link isn't erased by the lists still loading.
  useEffect(() => {
    const current = window.location.search;
    const next = writeDatasetsUrl(current, {
      search,
      memberSearch,
      sort,
      taskResultFilter,
      operatorFilter,
      datasetId: selectedDatasetId,
      membershipId: selectedMembershipId,
    });
    if (next === current.replace(/^\?/, '')) return;
    window.history.replaceState(
      null,
      '',
      next ? `${window.location.pathname}?${next}` : window.location.pathname,
    );
  }, [
    search,
    memberSearch,
    sort,
    taskResultFilter,
    operatorFilter,
    selectedDatasetId,
    selectedMembershipId,
  ]);

  // ---- mutations ---------------------------------------------------------

  const invalidateDatasets = useCallback(
    async (datasetId?: string | null) => {
      await queryClient.invalidateQueries({ queryKey: queryKeys.datasets });
      await queryClient.invalidateQueries({ queryKey: queryKeys.captures });
      if (datasetId) {
        await queryClient.invalidateQueries({ queryKey: queryKeys.dataset(datasetId) });
      }
    },
    [queryClient],
  );

  const createMutation = useMutation({
    mutationFn: () =>
      createDataset({
        name: newName.trim(),
        operator: newOperator.trim() || null,
        task: newTask.trim() || null,
      }),
    onSuccess: async (dataset) => {
      await invalidateDatasets(dataset.dataset_id);
      setCreateOpen(false);
      setNewName('');
      setNewOperator('');
      setNewTask('');
      setSelectedDatasetId(dataset.dataset_id);
      setSelectedMembershipId(null);
      showToast(`Created “${dataset.name}” — nothing was written under objects/`);
    },
  });

  const deleteDatasetMutation = useMutation({
    mutationFn: (datasetId: string) => deleteDataset(datasetId),
    onSuccess: async (_res, datasetId) => {
      queryClient.removeQueries({ queryKey: queryKeys.dataset(datasetId) });
      await invalidateDatasets();
      setConfirmingDatasetDelete(false);
      clearDataset();
      showToast('Dataset deleted — every recording it listed is untouched');
    },
  });

  const addMutation = useMutation({
    mutationFn: (capture: Capture) =>
      addDatasetMember(selectedDatasetId ?? '', capture.capture_id),
    onSuccess: async (member) => {
      await invalidateDatasets(member.dataset_id);
      showToast(`Added as #${member.display_index} — the recording did not move`);
    },
    onError: (error) => showToast(captureErrorText(error)),
  });

  const removeMutation = useMutation({
    mutationFn: (row: MemberRow) => removeDatasetMember(row.datasetId, row.membershipId),
    onSuccess: async (_res, row) => {
      await invalidateDatasets(row.datasetId);
      if (selectedMembershipId === row.membershipId) setSelectedMembershipId(null);
      showToast(
        `Removed #${row.displayIndex} — the recording is untouched and the ` +
          'number is not reused',
      );
    },
    onError: (error) => showToast(captureErrorText(error)),
  });

  // §12 obliges the discard dialog to say that a copy may remain on the robot —
  // but only where that is true. The pull channel's health check answers on a
  // split recording-PC deploy and nowhere else, so its availability IS "this is
  // a split deployment". Read once per session, on the key Review uses, so the
  // two screens share one probe and cannot disagree about the deployment they
  // are running on. On error the default (off) stands honestly.
  const transferStatusQuery = useQuery({
    queryKey: queryKeys.transferStatus,
    queryFn: ({ signal }) => apiGet<{ available?: boolean }>('/transfer/status', { signal }),
    staleTime: Infinity,
    refetchOnWindowFocus: false,
    retry: false,
  });

  const deletion = useCaptureDeletion({
    invalidate: useMemo(
      () =>
        selectedDatasetId
          ? [queryKeys.datasets, queryKeys.dataset(selectedDatasetId)]
          : [queryKeys.datasets],
      [selectedDatasetId],
    ),
    onDeleted: useCallback(() => setSelectedMembershipId(null), []),
    onToast: showToast,
  });

  // ---- archive -----------------------------------------------------------

  // Capability first: with no roots configured the archive control never renders
  // (do not offer what cannot run). The probe is addressed to a capture because
  // that is the route's shape, but it answers for the DEPLOYMENT — the handler
  // reads KAIROS_ARCHIVE_ROOTS and nothing about the capture — so one probe
  // governs every control on this screen.
  const probeCaptureId = captures[0]?.capture_id ?? null;
  const archiveConfigQuery = useQuery({
    queryKey: queryKeys.archiveConfig,
    queryFn: ({ signal }) => getArchiveConfig(probeCaptureId ?? '', signal),
    enabled: probeCaptureId !== null,
  });
  const archiveRoots = useMemo(
    () => archiveConfigQuery.data?.roots ?? [],
    [archiveConfigQuery.data],
  );
  const archiveEnabled = (archiveConfigQuery.data?.enabled ?? false) && archiveRoots.length > 0;

  // The backend refuses to archive a capture that still belongs to a dataset,
  // for the same reason it refuses to delete one: the dataset would be left
  // citing something that is no longer here. Offering the control anyway would
  // be offering a guaranteed failure.
  const canArchive = useCallback(
    (capture: Capture) =>
      archiveEnabled &&
      (capture.memberships ?? []).length === 0 &&
      availabilityOf(capture).usable,
    [archiveEnabled],
  );

  const effectiveRoot = archiveRoot || archiveRoots[0] || '';
  // Default subpath from the capture's OWN operator/task, and only those it
  // actually records — an archive tree then reads the way the catalog does,
  // without inventing an "unknown" folder for a capture that names neither.
  const defaultSubpath = archiveTarget
    ? [archiveTarget.operator, archiveTarget.task].filter(Boolean).join('/')
    : '';
  const subpath = archiveSubpath || defaultSubpath;
  const archiveDestination = effectiveRoot
    ? `${effectiveRoot.replace(/\/+$/, '')}${subpath ? `/${subpath.replace(/^\/+/, '')}` : ''}`
    : '';
  // The server writes into `<destination>/<capture_id>`, so the destination the
  // operator types is the PARENT. Both are shown; guessing which one is meant
  // is how an archive lands one level off.
  const archiveFinalPath =
    archiveDestination && archiveTarget
      ? `${archiveDestination}/${archiveTarget.capture_id}`
      : '';

  const archiveMutation = useMutation({
    mutationFn: (capture: Capture) =>
      archiveCapture(capture.capture_id, {
        destination: archiveDestination,
        operator: capture.operator ?? null,
        reason: archiveReason.trim() || null,
      }),
    onSuccess: async (res) => {
      await invalidateDatasets(selectedDatasetId);
      setArchiveTarget(null);
      setArchiveSubpath('');
      setArchiveReason('');
      showToast(
        res.verified
          ? `Archived to ${res.destination} — verified, then removed from this machine`
          : `Copied to ${res.destination}, but it did NOT verify — check it before ` +
              'trusting the copy',
      );
    },
  });

  const openArchive = useCallback((capture: Capture) => {
    setArchiveTarget(capture);
    setArchiveSubpath('');
    setArchiveReason('');
  }, []);
  const cancelArchive = useCallback(() => setArchiveTarget(null), []);

  // ---- candidates --------------------------------------------------------

  const memberCaptureIds = useMemo(
    () => new Set(scopeAllMembers.map((row) => row.captureId)),
    [scopeAllMembers],
  );
  const matchedCandidates = useMemo(
    () =>
      captures.filter(
        (capture) =>
          ADDABLE_STATES.has(capture.state) &&
          !memberCaptureIds.has(capture.capture_id) &&
          captureMatches(capture, debouncedCandidateSearch),
      ),
    [captures, memberCaptureIds, debouncedCandidateSearch],
  );

  return {
    rows,
    shown: rows.length,
    total: allRows.length,
    search,
    setSearch,
    sort,
    toggleSort,
    taskResultFilter,
    setTaskResultFilter,
    operatorFilter,
    setOperatorFilter,
    operatorOptions,

    selectedDatasetId,
    selectedDataset: selectedRow,
    selectDataset,
    isDatasetSelected: (datasetId) => selectedDatasetId === datasetId,
    clearDataset,

    createOpen,
    openCreate: () => setCreateOpen(true),
    cancelCreate: () => setCreateOpen(false),
    newName,
    setNewName,
    newOperator,
    setNewOperator,
    newTask,
    setNewTask,
    submitCreate: () => {
      if (newName.trim()) createMutation.mutate();
    },
    creating: createMutation.isPending,
    createError: createMutation.isError ? createMutation.error : null,

    confirmingDatasetDelete,
    requestDatasetDelete: () => setConfirmingDatasetDelete(selectedRow !== null),
    cancelDatasetDelete: () => setConfirmingDatasetDelete(false),
    confirmDatasetDelete: () => {
      if (selectedDatasetId) deleteDatasetMutation.mutate(selectedDatasetId);
    },
    deletingDataset: deleteDatasetMutation.isPending,
    datasetDeleteError: deleteDatasetMutation.isError ? deleteDatasetMutation.error : null,

    memberSearch,
    setMemberSearch,
    scopeMembers,
    memberRows,
    memberMatchCount: matchedMembers.length,
    page: currentPage,
    pageCount,
    pageSize: MEMBER_PAGE_SIZE,
    goToPage: (next) => setPage(Math.max(1, next)),
    scope,

    selected,
    selectMember,
    isMemberSelected: (row) => selected?.membershipId === row.membershipId,
    selectSummary,
    isSummaryActive: selected === null,

    detail: captureDetailQuery.data ?? null,
    detailLoading: selected !== null && captureDetailQuery.isPending,
    detailError: selected !== null && captureDetailQuery.isError,

    removeMember: (row) => removeMutation.mutate(row),
    removingMembershipId: removeMutation.isPending ? removeMutation.variables.membershipId : null,

    candidates: matchedCandidates.slice(0, CANDIDATE_LIMIT),
    candidateMatchCount: matchedCandidates.length,
    candidateSearch,
    setCandidateSearch,
    addMember: (capture) => addMutation.mutate(capture),
    addingCaptureId: addMutation.isPending ? addMutation.variables.capture_id : null,

    deletion,
    splitDeploy: transferStatusQuery.data?.available === true,

    archiveEnabled,
    archiveRoots,
    canArchive,
    archiveTarget,
    openArchive,
    cancelArchive,
    archiveRoot: effectiveRoot,
    setArchiveRoot,
    archiveSubpath: subpath,
    setArchiveSubpath,
    archiveDestination,
    archiveFinalPath,
    archiveReason,
    setArchiveReason,
    confirmArchive: () => {
      if (archiveTarget) archiveMutation.mutate(archiveTarget);
    },
    archiving: archiveMutation.isPending,
    archiveError: archiveMutation.isError ? archiveMutation.error : null,

    isLoading: listQuery.isPending || capturesQuery.isPending,
    isError: listQuery.isError || capturesQuery.isError,

    toast,
  };
}
